import { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import { updateUserProfile, deleteUserAccount, getAllUsers, createUserAccount, uploadUserFace } from '../../services/api.js';
import { useConnectivity } from '../../hooks/useConnectivity';
import ConfirmDialog from '../../components/shared/ConfirmDialog';
import EmptyState from '../../components/shared/EmptyState';

function getAuthUser() {
  const raw = localStorage.getItem('authUser');
  if (!raw) return null;
  try { return JSON.parse(raw); } catch { return null; }
}

const emptyForm = { name: '', email: '', password: '', role: 'participant' };

export default function ProfilePage() {
  const navigate = useNavigate();
  const currentUser = getAuthUser();

  if (!currentUser) {
    navigate('/login');
    return null;
  }

  const isStaff = currentUser.role === 'staff';
  const [mode, setMode] = useState('profile');

  return (
    <main className="page">
      <header className="topbar">
        <h1 className="page-title">Profile</h1>
      </header>

      {isStaff && (
        <div className="px-4 pb-3">
          <div className="segmented max-w-[260px] mx-auto">
            <button
              className={`segmented-btn ${mode === 'profile' ? 'segmented-btn-active' : ''}`}
              onClick={() => setMode('profile')}
            >
              My Profile
            </button>
            <button
              className={`segmented-btn ${mode === 'participants' ? 'segmented-btn-active' : ''}`}
              onClick={() => setMode('participants')}
            >
              Participants
            </button>
          </div>
        </div>
      )}

      {mode === 'profile' && <ProfileSection currentUser={currentUser} navigate={navigate} />}
      {mode === 'participants' && <ParticipantSection currentUser={currentUser} />}
    </main>
  );
}

function ProfileSection({ currentUser, navigate }) {
  const [name, setName] = useState(currentUser?.name || '');
  const [email, setEmail] = useState(currentUser?.email || '');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState('');
  const [error, setError] = useState('');
  const [confirmDelete, setConfirmDelete] = useState(false);

  const handleLogout = () => {
    localStorage.removeItem('authUser');
    navigate('/login');
  };

  const handleSave = async (event) => {
    event.preventDefault();
    setError('');
    setStatus('');

    try {
      const payload = { name, email };
      if (password) payload.password = password;

      const data = await updateUserProfile(payload, currentUser.token);
      localStorage.setItem('authUser', JSON.stringify({ ...currentUser, ...data, token: currentUser.token }));
      setStatus('Profile updated successfully');
      setPassword('');
    } catch (err) {
      setError(err.message || 'Profile update failed');
    }
  };

  const handleDelete = async () => {
    try {
      await deleteUserAccount({}, currentUser.token);
      localStorage.removeItem('authUser');
      navigate('/login');
    } catch (err) {
      setError(err.message || 'Account deletion failed');
    }
  };

  return (
    <div className="mx-auto w-full max-w-2xl space-y-4 px-4 pb-6">
      <div className="card-pad space-y-4">
        <div className="flex items-center gap-3">
          <div className="avatar avatar-lg avatar-accent">{currentUser.name?.charAt(0)}</div>
          <div className="min-w-0">
            <p className="title">{currentUser.name}</p>
            <p className="meta capitalize">{currentUser.role}</p>
          </div>
        </div>

        <form onSubmit={handleSave} className="space-y-4">
          <div className="field">
            <label className="field-label" htmlFor="profile-name">Full Name</label>
            <input id="profile-name" className="input" value={name} onChange={(event) => setName(event.target.value)} required />
          </div>
          <div className="field">
            <label className="field-label" htmlFor="profile-email">Email</label>
            <input id="profile-email" type="email" className="input" value={email} onChange={(event) => setEmail(event.target.value)} required />
          </div>
          <div className="field">
            <label className="field-label" htmlFor="profile-password">New Password</label>
            <input id="profile-password" type="password" className="input" value={password} onChange={(event) => setPassword(event.target.value)} />
          </div>
          {error && <p className="field-error">{error}</p>}
          {status && <div className="banner banner-success">{status}</div>}
          <button type="submit" className="btn btn-primary btn-lg btn-block">Save Profile</button>
        </form>
      </div>

      <div className="flex gap-2">
        <button className="btn btn-secondary btn-lg flex-1" onClick={handleLogout}>Logout</button>
        <button className="btn btn-danger btn-lg flex-1" onClick={() => setConfirmDelete(true)}>Delete Account</button>
      </div>

      <ConfirmDialog
        open={confirmDelete}
        title="Delete account?"
        message="This cannot be undone. Your account will be permanently removed."
        confirmLabel="Delete"
        danger
        onConfirm={handleDelete}
        onCancel={() => setConfirmDelete(false)}
      />
    </div>
  );
}

function ParticipantSection({ currentUser }) {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);

  const { isOnline } = useConnectivity();

  const [accounts, setAccounts] = useState([]);
  const [selected, setSelected] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');
  const [faceSource, setFaceSource] = useState(null);
  const [faceImageBase64, setFaceImageBase64] = useState(null);
  const [facePreview, setFacePreview] = useState(null);
  const [cameraActive, setCameraActive] = useState(false);
  const [uploadingFace, setUploadingFace] = useState(false);

  useEffect(() => {
    fetchAccounts();
  }, [isOnline]);

  useEffect(() => {
    const onSyncDone = () => fetchAccounts();
    window.addEventListener('sync:done', onSyncDone);
    return () => window.removeEventListener('sync:done', onSyncDone);
  }, []);

  const fetchAccounts = async () => {
    try {
      const data = await getAllUsers(currentUser.token);
      setAccounts(data);
    } catch (err) {
      setError(err.message || 'Unable to load accounts');
    }
  };

  const toBase64 = (blob) => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result.split(',')[1]);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });

  const handleUrlImage = async (url) => {
    try {
      const res = await fetch(url);
      const blob = await res.blob();
      const b64 = await toBase64(blob);
      setFaceImageBase64(b64);
      setFacePreview(URL.createObjectURL(blob));
    } catch {
      setError('Failed to load image from URL');
    }
  };

  const handleFileImage = (file) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const b64 = reader.result.split(',')[1];
      setFaceImageBase64(b64);
      setFacePreview(reader.result);
    };
    reader.onerror = () => setError('Failed to read image file');
    reader.readAsDataURL(file);
  };

  const startCamera = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
        setCameraActive(true);
      }
    } catch {
      setError('Camera access denied or not available');
    }
  }, []);

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    setCameraActive(false);
  }, []);

  const captureFromCamera = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0);
    const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
    setFaceImageBase64(dataUrl.split(',')[1]);
    setFacePreview(dataUrl);
    stopCamera();
    setFaceSource('camera');
  };

  const clearFace = () => {
    stopCamera();
    setFaceSource(null);
    setFaceImageBase64(null);
    setFacePreview(null);
  };

  useEffect(() => {
    return () => stopCamera();
  }, [stopCamera]);

  const handleCreate = async (event) => {
    event.preventDefault();
    setError('');
    setStatus('');
    setUploadingFace(false);

    if (!faceImageBase64) {
      setError('Face image is required — use URL, file upload, or camera');
      return;
    }

    try {
      const payload = { ...form };
      if (!navigator.onLine) {
        payload.faceImage = faceImageBase64;
      }
      const newUser = await createUserAccount(payload, currentUser.token);
      //use online status to determine whether to upload face
      if (navigator.onLine) {
        setUploadingFace(true);
        try {
          await uploadUserFace(newUser.id, faceImageBase64, currentUser.token);
        } catch (faceErr) {
          setError('Account created but face upload failed: ' + (faceErr.message || ''));
        }
        setUploadingFace(false);
        setStatus('Account created successfully with face registration');
        fetchAccounts();
      } else {
        setStatus('Account queued. face registration will complete when connection is restored');
        setAccounts(prev => [...prev, { ...newUser, id: 'pending-' + Date.now() }]);
      }
      setForm(emptyForm);
      clearFace();
    } catch (err) {
      setError(err.message || 'Create account failed');
    }
  };

  const handleSelect = (account) => {
    setSelected(account);
    setForm({
      name: account.name || '',
      email: account.email || '',
      password: '',
      role: account.role || 'participant',
    });
    setStatus('Editing ' + account.name);
    setError('');
    clearFace();
  };

  const handleUpdate = async (event) => {
    event.preventDefault();
    if (!selected) return;
    setError('');
    setStatus('');

    try {
      const payload = { targetId: selected.id, name: form.name, email: form.email, role: form.role };
      if (form.password) payload.password = form.password;

      await updateUserProfile(payload, currentUser.token);
      setStatus('Account updated successfully');
      setSelected(null);
      setForm(emptyForm);
      clearFace();
      //obtain account list based on connectivity
      if (navigator.onLine) {
        fetchAccounts();
      } else {
        setAccounts(prev => prev.map(a =>
          a.id === (payload.targetId || selected.id)
            ? { ...a, name: form.name, email: form.email, role: form.role }
            : a
        ));
      }
    } catch (err) {
      setError(err.message || 'Update failed');
    }
  };

  const handleDelete = async (accountId) => {
    setError('');
    setStatus('');

    try {
      await deleteUserAccount({ targetId: accountId }, currentUser.token);
      setStatus('Account deleted successfully');
      if (selected?.id === accountId) {
        setSelected(null);
        setForm(emptyForm);
      }
      if (navigator.onLine) {
        fetchAccounts();
      } else {
        setAccounts(prev => prev.filter(a => a.id !== accountId));
      }
    } catch (err) {
      setError(err.message || 'Delete failed');
    }
  };

  const handleCancelEdit = () => {
    setSelected(null);
    setForm(emptyForm);
    setStatus('');
    setError('');
    clearFace();
  };

  return (
    <div className="mx-auto w-full max-w-2xl space-y-4 px-4 pb-6">
      <div className="card-pad">
        <h2 className="title mb-4">Accounts</h2>

        {error && <p className="field-error mb-3">{error}</p>}
        {status && <div className="banner banner-success mb-3">{status}</div>}

        {accounts.length === 0 ? (
          <EmptyState icon={<PersonAddIcon />} title="No accounts yet" />
        ) : (
          <div className="space-y-2">
            {accounts.map((account) => (
              <div key={account.id} className="row rounded-xl border border-edge bg-surface-2">
                <div className="row-left">
                  <div className="row-text">
                    <span className="row-title">{account.name}</span>
                    <span className="meta">{account.email}</span>
                  </div>
                </div>
                <span className={`pill ${account.role === 'staff' ? 'pill-accent' : 'pill-neutral'}`}>{account.role}</span>
                <div className="row-actions">
                  <button className="btn btn-sm btn-ghost" type="button" onClick={() => handleSelect(account)}>Edit</button>
                  <button className="btn btn-sm btn-ghost text-bad" type="button" onClick={() => handleDelete(account.id)}>Delete</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="card-pad">
        <h2 className="title mb-4">{selected ? 'Edit Account' : 'Create Account'}</h2>

        <form onSubmit={selected ? handleUpdate : handleCreate} className="space-y-4">
          <div className="field">
            <label className="field-label" htmlFor="acc-name">Full Name</label>
            <input id="acc-name" className="input" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required />
          </div>
          <div className="field">
            <label className="field-label" htmlFor="acc-email">Email</label>
            <input id="acc-email" type="email" className="input" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required />
          </div>
          <div className="field">
            <label className="field-label" htmlFor="acc-password">Password</label>
            <input id="acc-password" type="password" className="input" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} placeholder={selected ? 'Leave blank to keep current' : ''} required={!selected} />
          </div>
          <div className="field">
            <label className="field-label" htmlFor="acc-role">Role</label>
            <select id="acc-role" className="select" value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })}>
              <option value="participant">Participant</option>
              <option value="staff">Staff</option>
            </select>
          </div>

          {!selected && (
            <fieldset className="space-y-3 rounded-xl border border-edge bg-surface-2 p-3">
              <legend className="field-label px-1">Face Registration <span className="text-bad">*</span></legend>
              <p className="meta">Attach a face image for facial recognition, required</p>

              <div className="segmented">
                {['url', 'file', 'camera'].map((src) => (
                  <button
                    key={src}
                    type="button"
                    className={`segmented-btn ${faceSource === src ? 'segmented-btn-active' : ''}`}
                    onClick={() => {
                      if (faceSource === src) { clearFace(); return; }
                      clearFace();
                      setFaceSource(src);
                      if (src === 'camera') startCamera();
                    }}
                  >
                    {src === 'url' ? 'URL' : src === 'file' ? 'Upload' : 'Camera'}
                  </button>
                ))}
              </div>

              {faceSource === 'url' && (
                <div className="flex gap-2">
                  <input type="url" placeholder="https://example.com/face.jpg" className="input" />
                  <button type="button" className="btn btn-secondary btn-sm shrink-0" onClick={(e) => handleUrlImage(e.target.previousElementSibling.value)}>Load</button>
                </div>
              )}

              {faceSource === 'file' && (
                <input type="file" accept="image/*" onChange={(e) => { const f = e.target.files[0]; if (f) handleFileImage(f); }} className="input" />
              )}

              {faceSource === 'camera' && (
                <div className="flex flex-col items-center gap-2">
                  <div className="camera-frame">
                    <video ref={videoRef} className="camera-video" playsInline muted />
                  </div>
                  <canvas ref={canvasRef} style={{ display: 'none' }} />
                  {cameraActive && (
                    <button type="button" className="btn btn-primary btn-sm" onClick={captureFromCamera}>Capture</button>
                  )}
                </div>
              )}

              {facePreview && (
                <div className="flex items-center gap-3">
                  <div className="avatar avatar-lg">
                    <img src={facePreview} alt="Face preview" className="h-full w-full rounded-full object-cover" />
                  </div>
                  <button type="button" className="btn btn-danger btn-sm" onClick={clearFace}>Remove</button>
                </div>
              )}
            </fieldset>
          )}

          <button className="btn btn-primary btn-lg btn-block" type="submit" disabled={uploadingFace || (!selected && !faceImageBase64)}>
            {uploadingFace && <span className="spinner-sm" />}
            {uploadingFace ? 'Uploading face...' : selected ? 'Update Account' : 'Create Account'}
          </button>
          {selected && (
            <button type="button" className="btn btn-secondary btn-lg btn-block" onClick={handleCancelEdit}>Cancel</button>
          )}
        </form>
      </div>
    </div>
  );
}
